package com.hotelmanagement.entity;
import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.util.List;
@Entity @Table(name="USERS") public class User {
 @Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="users_seq_gen") @SequenceGenerator(name="users_seq_gen",sequenceName="USERS_SEQ",allocationSize=1) @Column(name="ID") private Long id;
 @Column(unique=true,nullable=false,name="USERNAME") private String username; @Column(unique=true,nullable=false,name="EMAIL") private String email; @JsonIgnore @Column(nullable=false,name="PASSWORD") private String password; @Column(name="FIRST_NAME") private String firstName; @Column(name="LAST_NAME") private String lastName; @Column(name="PHONE_NUMBER") private String phoneNumber; @Column(name="ROLE") private String role="CUSTOMER";
 @JsonIgnore @OneToMany(mappedBy="user",cascade=CascadeType.ALL,fetch=FetchType.LAZY) private List<Booking> bookings;
 public User(){} public User(Long id,String username,String email,String password,String firstName,String lastName,String phoneNumber,String role){this.id=id;this.username=username;this.email=email;this.password=password;this.firstName=firstName;this.lastName=lastName;this.phoneNumber=phoneNumber;this.role=role;}
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getPhoneNumber(){return phoneNumber;} public void setPhoneNumber(String v){phoneNumber=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public List<Booking> getBookings(){return bookings;} public void setBookings(List<Booking> v){bookings=v;}
}